+        if (mode == null) {
+            return false;
+        }
+        return CLUSTER.equals(mode);
+    }
+
+    public static boolean isLocalMode(String mode) {
+        if (mode == null) {
+            return false;
+        }
+        return LOCAL.mode.equals(mode.toUpperCase());
+    }
+
+    public static boolean isLocalMode(ProxyMode mode) {
+        if (mode == null) {
+            return false;
+        }
+        return LOCAL.equals(mode);
+    }
