+        TopicRouteData topicRouteData = messageQueueView.getTopicRouteData();
+
+        ProxyTopicRouteData proxyTopicRouteData = new ProxyTopicRouteData();
+        proxyTopicRouteData.setQueueDatas(topicRouteData.getQueueDatas());
