+            List<MessageExt> messageExtList = new ArrayList<>();
+            switch (r.getCode()) {
+                case ResponseCode.SUCCESS:
+                    popStatus = PopStatus.FOUND;
+                    ByteBuffer byteBuffer = ByteBuffer.wrap(r.getBody());
+                    messageExtList = MessageDecoder.decodesBatch(
+                        byteBuffer,
