+        @Override
+        protected boolean processReadResult(ByteBuffer byteBufferRead) {
+            int readSocketPos = byteBufferRead.position();
+            try {
+                while (true) {
+                    int diff = byteBufferRead.position() - AutoSwitchHAClient.this.processPosition;
