+        return nettyClientConfig;
+    }
+
+    public BrokerHousekeepingService getBrokerHousekeepingService() {
+        return brokerHousekeepingService;
+    }
+
+    public Configuration getConfiguration() {
+        return configuration;
+    }
+}

