+        for (int i = 0; i < timerDist.size(); i++) {
+            int slotBeforeNum = i == 0 ? 0 : timerDist.get(i - 1) * 1000 / precisionMs;
+            int slotTotalNum = timerDist.get(i) * 1000 / precisionMs;
+            int periodTotal = 0;
+            for (int j = slotBeforeNum; j < slotTotalNum; j++) {
