+                    }
+                } catch (Exception e) {
+                    log.error("Recover timerlog error", e);
+                    stopCheck = true;
+                    break;
+                }
+            }
+            sbr.release();
+            checkOffset = mappedFiles.get(index).getFileFromOffset() + position;
+            if (stopCheck) {
+                break;
+            }
+        }
+        if (checkTimerLog) {
+            timerLog.getMappedFileQueue().truncateDirtyFiles(checkOffset);
+        }
+        return checkOffset;
+    }
