+                        } else {
+                            holdMomentForUnknownError();
+                        }
+                    }
+                    commitQueueOffset = trs.get(trs.size() - 1).getMsg().getQueueOffset();
+                    maybeMoveWriteTime();
+                } catch (Throwable e) {
