+                                if (needDelete(tr.getMagic()) && !needRoll(tr.getMagic())) {
+                                    if (msgExt.getProperty(MessageConst.PROPERTY_TIMER_DEL_UNIQKEY) != null && tr.getDeleteList() != null) {
